(function(){
  var $=function(id){return document.getElementById(id)};
  var synth=window.speechSynthesis;
  if(!synth||typeof SpeechSynthesisUtterance==='undefined'){
    $('err').hidden=false;
    $('err').textContent='This browser cannot read text aloud. Chrome, Edge and Safari all can, and so does Firefox on most systems.';
    ['play','pause','stop'].forEach(function(i){$(i).disabled=true});
    if(window.WT) WT.resize();
    return;
  }
  var voices=[], current=null, utter=null;

  function loadVoices(){
    voices=synth.getVoices()||[];
    if(!voices.length) return;
    // language filter, built from whatever this device actually has
    var langs={};
    voices.forEach(function(v){ langs[v.lang]=(langs[v.lang]||0)+1 });
    var keys=Object.keys(langs).sort();
    $('lang').innerHTML='<option value="">All languages ('+voices.length+')</option>'+
      keys.map(function(l){return '<option value="'+l+'">'+l+' ('+langs[l]+')</option>'}).join('');
    fillVoices();
  }
  function fillVoices(){
    var f=$('lang').value;
    var list=voices.filter(function(v){ return !f || v.lang===f });
    if(!list.length) list=voices;
    $('voice').innerHTML=list.map(function(v,i){
      return '<option value="'+voices.indexOf(v)+'">'+v.name+' | '+v.lang+(v.default?' (default)':'')+'</option>';
    }).join('');
    current=voices[+$('voice').value]||list[0];
    $('note').textContent=voices.length+' voice'+(voices.length>1?'s':'')+
      ' available on this device. The list comes from your operating system, so it differs between computers and phones.';
    if(window.WT) WT.resize();
  }
  // Chrome populates voices asynchronously, so both paths are needed.
  loadVoices();
  synth.onvoiceschanged=loadVoices;

  function counts(){
    var t=$('txt').value;
    var words=t.trim()?t.trim().split(/\s+/).length:0;
    $('nchar').textContent=t.length;
    $('nword').textContent=words;
    // about 150 words a minute at normal speed, scaled by the rate
    var secs=words?Math.round(words/150*60/(+$('rate').value||1)):0;
    $('ntime').textContent=Math.floor(secs/60)+':'+String(secs%60).padStart(2,'0');
  }

  function speak(){
    var text=$('txt').value.trim();
    if(!text){ $('note').textContent='Type or paste some text first.'; return; }
    synth.cancel();
    utter=new SpeechSynthesisUtterance(text);
    if(current) utter.voice=current;
    utter.rate=+$('rate').value; utter.pitch=+$('pitch').value;
    utter.onstart=function(){ $('play').textContent='Playing'; $('play').disabled=true;
      $('pause').disabled=false; $('stop').disabled=false; $('txt').classList.add('tts-speaking'); };
    utter.onend=reset;
    utter.onerror=function(e){
      // 'interrupted' and 'canceled' are what Stop produces, not failures
      if(e.error&&e.error!=='interrupted'&&e.error!=='canceled'){
        $('err').hidden=false; $('err').textContent='Playback stopped: '+e.error+'.';
      }
      reset();
    };
    $('err').hidden=true;
    synth.speak(utter);
  }
  function reset(){
    $('play').textContent='Play'; $('play').disabled=false;
    $('pause').textContent='Pause'; $('pause').disabled=true; $('stop').disabled=true;
    $('txt').classList.remove('tts-speaking');
    if(window.WT) WT.resize();
  }
  $('play').addEventListener('click',speak);
  $('pause').addEventListener('click',function(){
    if(synth.paused){ synth.resume(); this.textContent='Pause'; }
    else { synth.pause(); this.textContent='Resume'; }
  });
  $('stop').addEventListener('click',function(){ synth.cancel(); reset(); });
  $('txt').addEventListener('input',counts);
  $('rate').addEventListener('input',function(){ $('rateV').textContent=(+this.value).toFixed(1)+'x'; counts(); });
  $('pitch').addEventListener('input',function(){ $('pitchV').textContent=(+this.value).toFixed(1); });
  $('lang').addEventListener('change',fillVoices);
  $('voice').addEventListener('change',function(){ current=voices[+this.value]; });
  // Some browsers keep speaking after the page is hidden; stop cleanly.
  window.addEventListener('pagehide',function(){ synth.cancel(); });
  counts();
})();
